INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('f591603b-9632-4842-a447-66f9bb21213e', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 69.7, 141.04, 'Then we drew a decision tree, and we got this bound that if I had n outputs, I would require my decision tree to be at least log n height. And so in this model, I can''t find the things in faster than log n time. But luckily, we are in a model of computation which has a stronger operation, namely random accessing. And if we stored the things that we''re looking for, we have unique keys, and those keys are integers, then if I have an item with key k, if I store it at index k in my array, then I can find it and manipulate it in constant time. That''s pretty cool. That''s what we called a direct access array. A direct access array is really not different than a regular array, except how we were using it when we were talking about sequences is we were giving kind of extrinsic semantics to the slots where we were storing these things.', '', '[-0.07196045,-0.0287323,0.015075684,-0.046905518,0.0038776398,0.023025513,0.059661865,0.033355713,0.078552246,-0.044525146,0.011856079,0.010040283,0.038482666,0.025054932,-0.017852783,-0.003118515,-0.041931152,-0.0154800415,-0.038726807,0.04019165,0.097473145,-0.027160645,-0.068847656,-0.0791626,0.0256958,0.026870728,-0.044403076,-0.0077552795,-0.024765015,-0.22607422,0.005996704,-0.05029297,0.0814209,-0.013580322,-0.031463623,-0.053741455,-0.045410156,0.061187744,-0.064819336,0.05065918,0.065979004,0.043792725,-0.018829346,-0.015426636,-0.014076233,-0.027893066,-0.04776001,-0.007446289,0.007003784,-0.03286743,-0.030059814,0.018981934,0.029525757,0.035705566,0.023086548,0.003917694,0.05886841,-0.016677856,0.052215576,-0.00422287,0.037750244,0.028076172,-0.1282959,0.07885742,0.041107178,0.010032654,-0.022644043,-0.04269409,0.060577393,0.059631348,-0.0146484375,0.046295166,0.010887146,0.034057617,0.049072266,-0.042999268,-0.006549835,-0.068