INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('63fe469c-2339-4728-8d49-c272d47e7835', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 141.04, 201.36, 'Basically, I could put any item in any slot, right? Where it was in my array had nothing to do with what those things were. Here, we are imposing intrinsic semantics on my array that if I have an item with k k, it must be at index k. That''s the thing that we''re taking advantage of here. And then we can use this nice, powerful, linear branching, random access operation to find that thing in constant time, because that''s our model of computation. OK. Then what was the problem with this direct access array? Anyone shout it out? Space. Right. So we had to instantiate a direct access array that was the size of the space of our keys, right? In general, my index location could go from zero to some positive number, right?', '', '[-0.07183838,-0.053649902,0.0043411255,-0.040405273,-0.020019531,-0.022567749,0.08258057,0.04623413,0.053588867,-0.05859375,0.051086426,-0.020706177,0.02885437,0.02609253,-0.0013856888,-0.0059394836,-0.037597656,-0.010559082,-0.042388916,0.036895752,0.083862305,-0.02885437,-0.030914307,-0.07989502,0.023132324,0.076538086,-0.060668945,-0.00028324127,-0.0423584,-0.25097656,-0.03930664,-0.051574707,0.06744385,0.0074768066,-0.006778717,-0.066101074,-0.032287598,0.045684814,-0.08416748,0.04824829,0.055755615,0.03579712,-0.027511597,0.0028629303,-0.025299072,-0.039642334,-0.04827881,-0.00031542778,0.00957489,-0.04019165,-0.012382507,0.033355713,0.009498596,0.06414795,0.0047340393,0.0016860962,0.058258057,0.0037174225,0.03488159,0.021621704,0.055877686,0.028274536,-0.14379883,0.07489014,0.046813965,-0.023376465,0.0077552795,-0.037750244,0.008903503,0.034088135,0.023223877,0.038513184,0.0027713776,0.04522705,0.05517578,-0.07055664,-0.012145996,-0.029663086,0.061706543,0.035095215,-0.041992188,-0.0803833,0.005870819,0.0074920654,-0.04232788,-0.008834839,-0.0