INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('50c95ff9-d3a6-4705-a3b4-84f3a0335da1', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 201.36, 288.28, 'If I have very large positive numbers, if I was searching among your MIT IDs, I''d have to have a direct access array that spans that space of possible keys you could have, right? And that could be much larger than n. And so the rest of the time, we talked about how to fix that space problem. We can reduce the space by taking that larger key space from zero to u, which could be very large, and map it down to a small space. Now, in general, if I give you a fixed hash function there, that''s not going to be good for all inputs. If your inputs are very well distributed over the key space, then it is good. But in general, there would be hash functions with some inputs that will be bad, right? That''s what we kind of argued. And so for the rest of the time there, we talked about hash families choosing a hash function randomly from among a large set of hash functions, which had a property that if I chose this thing randomly and you, generating your input, didn''t know which random numbers I was picking, the expectation over my random choice, me, I''m the one running the algorithm, not you giving me the input, that random choice, my algorithm actually behaves really well in expectation.', '', '[-0.047180176,-0.040649414,0.0074157715,-0.05734253,-0.015075684,0.0021686554,0.04840088,0.02003479,0.052886963,-0.026168823,0.006462097,-0.016708374,0.047668457,0.02998352,-0.0418396,0.028076172,0.0013208389,0.0022296906,-0.08300781,0.022705078,0.04675293,0.013191223,-0.021484375,-0.076416016,-0.0209198,0.018737793,-0.020996094,-0.04458618,-0.036346436,-0.23876953,0.028274536,-0.028945923,0.10827637,-0.035583496,-0.021118164,-0.03366089,-0.0057754517,0.049804688,-0.048583984,0.07086182,0.055603027,0.019821167,-0.007408142,-0.011421204,0.007396698,-0.045806885,-0.046173096,-0.03756714,-