INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('011d3afe-acef-4e53-b96e-910357cd94e3', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 377.48, 437.9, 'You''ve got comparison operations like, are they equal, less than, greater than, maybe greater than or equal, less than or equal, right? Generally, you have all these operations that you could do, maybe not equal, right? But the key thing here is that there are only two possible outputs to each of these comparators, right? There''s only two things. There''s only one thing that I can branch on. It''s going to branch into two different lines, right? It''s either true, and I do some other computation, or it''s false, and I''ll do a different set of computation, right? Does that make sense? So what I''m going to do is I''m going to view an algorithm in the comparison model as what I like to call a decision tree, right? So if I specify an algorithm to you, the first thing it''s going to do, if I don''t compare items at all, I''m kind of screwed, because I''ll never be able to tell if my key is in there or not.', '', '[-0.051483154,-0.029800415,-0.019165039,-0.033203125,0.004688263,0.00712204,0.08013916,0.017074585,0.08300781,-0.052947998,-0.0075683594,-0.03579712,0.049468994,0.049743652,-0.0059432983,-0.02293396,0.00032639503,0.017242432,-0.070617676,0.029144287,0.075805664,-0.014549255,-0.057525635,-0.06726074,0.033233643,0.023391724,-0.03857422,-0.016159058,-0.049041748,-0.26513672,-0.020233154,-0.0715332,0.07928467,-0.028137207,-0.021896362,-0.02041626,-0.029907227,0.033813477,-0.06549072,0.04321289,0.059417725,-0.005607605,-0.0064468384,0.007511139,-0.032684326,-0.05960083,-0.054473877,0.02810669,-0.015411377,-0.051605225,0.027435303,-0.041809082,-0.019165039,-0.0033569336,0.05154419,0.027175903,0.051940918,0.0690918,0.04736328,0.023529053,0.058624268,0.032470703,-0.1628418,0.07336426,0.022201538,0.028457642,-0.021331787,-0.064208984,0.006969452,0.08886719,0.021621704,0.