INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('ad142e47-4a0f-4c71-ad27-17d8359a3731', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 288.28, 358.44, 'In particular, I got constant time for finding, inserting, and deleting into this data structure in expectation. We did a little proof of that the chain lengths, where we stored collisions in our hash function, in our hash table, sorry, those wouldn''t be very long. And so if they were constant, then I don''t have to search more than a constant number of things when I go to a hashed index location. Does everyone remember what we talked about last week? And we then, I didn''t show you this chart at the end, but I''m showing it to you now. Essentially what we had was we have a bunch of different ways to deal with this set interface. And last week, we talked about the sorted array, and then we talked about this direct access array in this hash table, right? Which do better for these dictionary, the find and insert and delete operations, or at least better in an expected sense, right?', '', '[-0.075805664,-0.042144775,0.025024414,-0.03656006,0.047088623,-0.009521484,0.055145264,0.02178955,0.06222534,-0.030853271,0.020141602,0.0037059784,0.0619812,0.0440979,-0.027359009,0.008850098,-0.01838684,-0.024093628,-0.060424805,0.04324341,0.06109619,-0.04421997,-0.039367676,-0.059570312,0.023208618,0.09631348,-0.035736084,-0.031402588,-0.031677246,-0.25634766,0.027938843,-0.049682617,0.053894043,-0.037261963,-0.04067993,-0.026153564,-0.018218994,0.08099365,-0.04196167,0.06121826,0.027862549,0.0151901245,-0.0418396,-0.017227173,-0.026367188,-0.027740479,-0.059143066,-0.023788452,0.0076942444,-0.025360107,-0.02407837,-0.0018405914,0.02822876,0.03744507,0.048431396,0.045562744,0.0848999,0.033172607,0.024124146,0.017623901,0.055633545,0.04168701,-0.12219238,0.10003662,0.07232666,0.02128601,0.010177612,-0.05822754,0.042053223,0.068603516,-0.015960693,0.044067383,0.030441284,0.089904785,0