INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('bc5bb826-d526-4a0a-b100-79ff92a87562', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 358.44, 426.84, 'What''s the worst case performance of a hash table? If I have to look up something in a hash table, and I happen to choose a bad hash function, what''s the worst case here? What? N, right? It''s worse than a sorted array, right? Because potentially I hashed everything that I was storing to the same index in my hash table, and to be able to distinguish between them, I can''t do anything more than a linear search, right? I mean, I could store another set''s data structure as my chain and do better that way. That''s actually how Java does it. They store data structure we''re going to be talking about next week as the chains so that they can get worst case log n. But in general, that hash table is only good if we''re allowing, OK, I want this to be expected good, but in the worst case, if I really need that operation to be worst case, right, I really can''t afford linear time ever for an operation of that kind, then I don''t want to use a hash table.', '', '[-0.03869629,-0.011375427,-0.019073486,-0.034606934,0.015586853,0.008232117,0.057128906,0.0018501282,0.0335083,-0.01626587,0.035583496,0.00141716,0.06628418,0.039916992,-0.0027885437,-0.009422302,0.0010480881,0.010131836,-0.044891357,0.027526855,0.05456543,-0.04788208,-0.030532837,-0.07495117,0.029693604,0.0736084,-0.068603516,-0.043823242,-0.056488037,-0.22131348,0.009513855,-0.051727295,0.0491333,-0.04534912,-0.04257202,-0.031082153,0.008003235,0.072631836,-0.043273926,0.040527344,0.014709473,0.052368164,-0.05718994,-0.022140503,-0.03555298,-0.03463745,-0.026916504,-0.04800415,0.02180481,-0.019195557,-0.031341553,0.01474762,0.0385437,0.011894226,0.05316162,0.0006375313,0.0736084,0.037078857,-0.001253128,0.03604126,0.04953003,0.03111267,-0.10620117,0.062561035,0.074035645,0.0077171326,-0.00844574,-0.05911255,-0.0006322