INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('3c45ca91-85ab-4054-becd-51ea469fa287', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 426.84, 495.56, 'And so on your pset 2, everything we ask you for is worst case, so probably you don''t want to be using hash tables, right? OK. Yes? What does the subscript e mean? That''s great. In this chart, I put a subscript on this is an expected runtime, right? Or an a, meaning this is an amortized runtime. At the end, we talked about how if we had too many things in our hash table, then as long as we didn''t do it too often, right, this is a little hand wavy argument, but the same kinds of ideas as the dynamic array, if whenever we got a linear, we were more than a linear factor away from where we were trying, basically the fill factor we were trying to be, then we could just completely rebuild the hash table with a new hash function randomly chosen from our hash table with a new size, and we could get amortized bounds. And so that''s what Python, how Python implements dictionaries or sets or even objects when it''s trying to map keys to different things.', '', '[-0.056640625,-0.037353516,0.029296875,-0.068359375,0.020721436,-0.0073432922,0.07336426,0.036865234,0.025283813,0.02192688,0.016571045,-0.06970215,0.060180664,0.020812988,-0.029403687,-0.018005371,-0.043518066,0.0023212433,-0.07598877,0.023391724,0.089904785,-0.01537323,-0.013671875,-0.078063965,0.024597168,0.09057617,-0.011650085,-0.025360107,-0.049743652,-0.26171875,0.016036987,-0.020355225,0.029571533,-0.024139404,-0.016708374,-0.028076172,-0.03225708,0.08026123,-0.040771484,0.09307861,0.025741577,0.022521973,-0.024215698,-0.025115967,0.005645752,-0.05722046,-0.0597229,-0.046203613,-0.0049705505,-0.049682617,-0.02305603,0.009780884,0.016677856,-0.004219055,0.037231445,0.031585693,0.04748535,0.060180664,0.046569824,0.018753052,0.021102905,0.06933594,-0.13366699,0.077697754,0.08807373,0.030197144,-0.030715942,-0.02468