INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('250a91c2-971e-443d-a0a5-2d124ab1f541', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 564.76, 625.8, 'And so I have to look down a chain to see where it is. However, if I happen to know that all of my keys are unique in my input, right, all the items I''m trying to store are unique, then I don''t have to do that check and I can get worst case linear time. Does that make sense? All right. It''s a subtlety, but that''s a great question. OK. So today, instead of talking about searching, we''re talking about sorting. OK. Last week, we saw a few ways to do sort. Some of them were quadratic, insertion sort and selection sort. And then we had one that was n log n. And this thing, n log n, seemed pretty good, but can I do better? Right? Can I do better? Well, what we''re going to show at the beginning of this class is, in this comparison model, no. n log n is optimal. And we''re going to go through the exact same line of reasoning that we had last week.', '', '[-0.079833984,-0.037353516,-0.021743774,-0.043640137,0.00075674057,0.010856628,0.05114746,0.025848389,0.044799805,-0.034088135,0.04510498,-0.007671356,0.03717041,0.074035645,-0.0020370483,-0.014930725,-0.013343811,0.0052757263,-0.05105591,0.008308411,0.03878784,-0.02659607,-0.06854248,-0.068115234,0.03149414,0.041656494,-0.015022278,-0.013328552,-0.03289795,-0.28076172,-0.01550293,-0.037719727,0.11383057,-0.026351929,-0.021347046,-0.043518066,-0.01777649,0.07122803,-0.03656006,0.0057525635,0.02909851,-0.0029296875,-0.033111572,-0.031829834,0.006504059,-0.039154053,-0.037628174,0.011077881,-0.016677856,-0.05041504,-0.022201538,-0.025680542,0.01399231,0.025024414,0.026367188,0.041168213,0.0513916,0.01449585,0.030776978,0.027999878,0.064941406,0.04385376,-0.14428711,0.10992432,0.0524292,0.0118637085,-0.03527832,-0.0647583,0.015136719,0.09185791,0.016281128,0.009849548,0.012435913,0.061340332,0.023834229,-0.02168274,-0.009223