INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('b82ea7f8-d30b-49bb-8834-65f58a5faded', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 625.8, 690.36, 'So in the comparison model, what did we use when we were trying to make this argument that any comparison model algorithm was going to take at least log n time? What we did was we said, OK, I can think of any model in the comparison model, any algorithm in the comparison model, as kind of this, some comparisons happen. They branch in a binary sense, but you could have it generalized to any constant branching factor. But for our purposes, binary is fine. And what we said was that there were at least n outputs, really n plus 1, but, you know, at least order n outputs. And we showed that, or we argued to you, that the height of this tree had to be at least log n, right?', '', '[-0.091918945,0.016983032,0.0039787292,-0.05105591,0.04055786,0.023147583,0.015205383,0.030776978,0.05340576,-0.02633667,0.017349243,-0.041625977,-0.0042266846,0.05340576,-0.0012903214,-0.006336212,-0.04837036,-0.04421997,-0.04800415,0.020629883,0.087402344,-0.012901306,-0.04348755,-0.059814453,0.06088257,0.0154418945,-0.047058105,-0.012107849,-0.0016174316,-0.24255371,-0.007873535,-0.025375366,0.09667969,-0.027755737,-0.012565613,-0.009017944,-0.0043525696,0.03375244,-0.0637207,0.034332275,0.061553955,0.050994873,-0.0067977905,0.009590149,-0.021636963,-0.055511475,-0.05847168,0.016967773,-0.029785156,-0.021636963,0.038482666,-0.042816162,0.019042969,0.00422287,0.021057129,0.051574707,0.060943604,0.015808105,0.0519104,-0.031158447,0.04156494,0.05053711,-0.20874023,0.075805664,0.05105591,0.048461914,-0.017105103,-0.05496216,0.03781128,0.09625244,-0.0056877136,0.007637024,9.596348e-05,0.026382446,0.008796692,0.0019741058,-0.0017433167,-0.053100586,0.020645142,-0.004245758,-0.0385437,-0.036621094,-0.045074463,-0.0065612793,-0.009284973,-0.03692627,-0.028213501,-0.03250122,0.040740967,0.007194519,0.00786