INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('44976eca-2034-4a14-a6de-0400060616d7', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 941.08, 1003.04, 'Well, I have a bunch of things here. That''s n factorial. Half of these things, these half, n over two things, are bigger than or equal to n over two. Does that make sense? So I can certainly lower bound this thing by n over two to the n over two. That''s a little easier thing to take a log of, right? If you take a log of that, that''s asymptotically n log n. So what we''re getting here is any sorting algorithm here takes at least n log n comparisons. And so merge sorts the best we can do. OK? Does that make sense to everybody? We''re just piggybacking on the analysis we had about decision trees connecting leaves with the minimum height of any binary tree on that number of leaves.', '', '[-0.062927246,0.006690979,-0.008049011,-0.06488037,0.02734375,0.03793335,0.04763794,0.019592285,0.06536865,-0.0037841797,-0.000893116,-0.04562378,0.038635254,0.075683594,0.0037174225,0.027191162,-0.015731812,-0.020858765,-0.07385254,0.032836914,0.05117798,-0.018478394,-0.03805542,-0.08276367,0.049804688,0.022277832,-0.06878662,-0.04296875,-0.0289917,-0.23596191,0.015945435,-0.009307861,0.062164307,-0.043762207,-0.015571594,-0.021240234,-0.00058555603,0.04220581,-0.063964844,-0.0052757263,0.03100586,0.04837036,-0.021850586,-0.05758667,0.008262634,-0.058135986,-0.044891357,0.015487671,-0.026397705,-0.037139893,0.016281128,-0.055541992,0.012077332,0.040863037,0.016235352,0.037139893,0.026824951,0.044189453,0.03955078,0.03741455,0.05657959,0.044555664,-0.14453125,0.064208984,0.056793213,-0.010383606,-0.042144775,-0.05227661,-0.0026569366,0.11315918,0.022888184,0.03918457,0.023727417,0.055908203,0.016906738,-0.015975952,-0.037200928,-0.058654785,-0.0021247864,0.019683838,-0.07434082,-0.024490356,-0.035583496,0.017654419,-0.011497498,-0.059661865,-0.016906738,-0.062561035,0.027938843,-0.015