INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('cce3abe7-8879-41d3-834f-ee583833e95a', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 1063.22, 1125.18, 'But what we did last week was use random access and a direct access array to do better. OK? So can anyone think of how to use that idea to sort faster? And I''m going to give you a caveat here. I''m going to let you assume that the keys of the things you''re trying to sort are unique. OK? And say they''re in a small range. So how could I use a direct access array to sort faster? Any ideas? Yeah? So you literally can start to do like a different aspect. Uh-huh. And then you look at that array and that''ll sort. OK. So what your colleague is saying is exactly correct. It''s something that I like to call direct access array sort. We won''t really call it that because there''s something more general that we''ll talk about in just a second.', '', '[-0.05593872,-0.059387207,-0.008140564,-0.066101074,0.018478394,0.014984131,0.014251709,0.02432251,0.03086853,-0.07751465,0.02722168,0.013412476,0.033325195,0.059020996,0.012268066,-0.020523071,-0.002319336,0.012702942,-0.043945312,0.019699097,0.04840088,-0.008071899,-0.03527832,-0.06866455,-0.0015993118,0.05340576,-0.0635376,0.0020427704,-0.066711426,-0.21936035,-0.03515625,-0.052001953,0.07141113,-0.022140503,-0.022369385,-0.08673096,-0.035461426,0.08300781,-0.06781006,0.041107178,0.06304932,-0.0011024475,-0.056884766,-0.01828003,-0.037475586,0.0028820038,-0.05203247,0.00028705597,0.005695343,-0.020706177,-0.02519226,0.01361084,0.008323669,0.029891968,0.020889282,0.012191772,0.06530762,0.02267456,0.01927185,0.026412964,0.062561035,0.024642944,-0.14257812,0.1105957,0.06463623,0.0056533813,-0.005176544,-0.039733887,0.022277832,0.03881836,-0.009292603,0.028305054,-0.012367249,0.049865723,0.04046631,-0.08404541,-0.017440796,-0.05508423,0.028808594,0.037994385,-0.050567627,-0.054534912,-0.012649536,-0.019760132,-0.025680542,-0.0029