INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('27bfa7ed-debb-44ba-9bf1-437b9e9bb903', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 2252.54, 2313.86, 'That''s something we could do. OK? How long would that take? Well, let''s say I didn''t use half of my more significant set of digits, right? Say I''m only using n over 2, or that''s not quite going to get what I want. Say again? Say again? . So what we''re going to do if we have direct access array sort, if I then go into each one of these digits and try to sort the things that are in there, that''s going to take time, right? It''s going to take time per each of those digits. Now, there might be a ton of collisions into one of the things, and so I might take more time to sort that than linear. Does that make sense? So I would prefer to do this tuple sort kind of behavior, sorting the smaller thing, sorting the bigger thing.', '', '[-0.08135986,-0.05609131,0.022125244,-0.06976318,-0.016342163,0.05331421,0.032318115,0.0023002625,0.04055786,-0.041778564,0.013664246,-0.0040740967,0.02760315,0.05911255,0.0051116943,-0.0115737915,0.010894775,0.0032596588,-0.058410645,0.010856628,0.059906006,-0.0029830933,-0.042541504,-0.046569824,0.0058403015,0.046539307,-0.049682617,-0.040374756,-0.056671143,-0.22790527,0.0011091232,-0.017166138,0.10180664,-0.025985718,-0.016616821,-0.07348633,-0.048461914,0.07470703,-0.066711426,0.031402588,0.052246094,0.015541077,-0.025100708,-0.032287598,-0.056365967,-0.011566162,-0.05883789,0.016784668,0.021484375,-0.039367676,-0.012077332,-0.023254395,0.013473511,0.036010742,0.032165527,0.0043144226,0.06817627,-0.0022773743,0.02520752,0.017608643,0.066467285,-0.008216858,-0.113708496,0.06463623,0.04019165,-0.0052871704,-0.017959595,-0.058746338,0.0020656586,0.08917236,-0.023132324,0.029006958,0.019973755,0.085632324,0.04550171,-0.050750732,-0.025680542,-0.063964844,0.017959595,0.074401855,-0.03692627,-0.035736084,0.00090932846,-0.008659363,-0.011734