INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('6d1362a9-bf6e-4bef-a150-a74a5e072f02', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 2377.92, 2445.72, 'Right? Why can''t we put a list there? That''s exactly what we do. This is called counting sort. And what we do here is we still have this direct access array, and we''re going to put a space u minus 0 to u minus 1. But instead of storing one thing here, at each key k, we store a pointer to a chain. This sounds like hashing, right? But the important thing is that I need to make sure, as I''m inserting things in here, then I''m maintaining the order in which they came in. Right? I can''t just throw them willy-nilly, or else we have this problem up here that we had before. Right? So I need what I would say is a sequence data structure. Right? Something that will maintain the order that I, the extrinsic order that I had when I''m putting these things in. Right? So as I have multiple things with k, right, I''m going to put them in the order.', '', '[-0.065979004,-0.0496521,-0.0069084167,-0.066223145,-0.0211792,0.028396606,0.067871094,0.0087890625,0.06112671,-0.020858765,0.014717102,-0.016021729,0.0385437,0.07269287,-0.0044403076,-0.033172607,-0.03503418,0.038330078,-0.045318604,-0.005706787,0.07977295,-0.021194458,-0.049224854,-0.041168213,0.011962891,0.06347656,-0.03591919,-0.021774292,-0.05255127,-0.23461914,-0.01576233,-0.06512451,0.08666992,-0.024887085,-0.034332275,-0.050201416,-0.05545044,0.057739258,-0.096191406,0.06616211,0.05834961,0.016967773,-0.044525146,-0.03265381,-0.017211914,-0.014183044,-0.045715332,-0.015991211,0.052490234,-0.069885254,-0.0014944077,0.029205322,-0.015960693,0.057250977,0.05557251,0.011650085,0.06567383,-0.013717651,0.021316528,-0.0031929016,0.06390381,0.02128601,-0.105285645,0.08148193,0.018295288,-0.0067825317,-0.008834839,-0.027053833,0.016021729,0.05960083,0.0018444061,0.0028305054,-0.019134521,0.07763672,0.037322998,-0.100097656,0.00