INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('f2197faa-5746-4882-a70c-a0c6b76e6776', 'c6cc3ea8-b3f0-4326-85da-c499d06dcb79', 2764.22, 2827.22, 'How many digits would I have there? How many size n digits would I need to represent a number of size n cubed? Any ideas? What did we do here? We divided off an n. We took it and stored it. We''re left with something of size n, right? If I had a number of size n cubed, I could divide off an n. I''m left with something of n squared. I don''t know how to deal with something of n squared. Actually, I do. What did I do? I can split it up into two size n numbers, right? So, if I had numbers bound, upper bounded by a cubic, right, n cubed, I could split it up into three digits. Three is still constant, right? And so I could split it up into three digits, tuples sort them in their increasing priority, and sort those.', '', '[-0.056732178,-0.01574707,0.0038967133,-0.04776001,-0.014625549,0.049743652,0.049072266,-0.0064582825,0.0006055832,-0.013244629,0.02357483,-0.05267334,0.07434082,0.031402588,0.009979248,-0.015808105,-0.03253174,0.012504578,-0.07287598,0.03918457,0.09741211,-0.023788452,-0.040100098,-0.041534424,0.030059814,0.043151855,-0.04876709,-0.07543945,-0.03363037,-0.22033691,-0.035736084,-0.0076179504,0.09075928,-0.07788086,0.025619507,-0.057373047,-0.028045654,0.062438965,-0.041656494,0.020568848,0.03942871,0.060668945,-0.006919861,-0.046936035,-0.018051147,-0.03970337,-0.034362793,0.0037212372,0.055389404,-0.048706055,0.019363403,-0.025466919,-0.011917114,0.0690918,0.030441284,0.027740479,0.041381836,0.022125244,0.011528015,0.02760315,0.08099365,0.016906738,-0.13378906,0.099609375,0.04559326,-0.0015010834,-0.03753662,-0.04373169,0.011482239,0.10803223,-0.030914307,0.014427185,-0.036590576,0.093322754,0.012886047,-0.019378662,-0.029281616,-0.050964355,0.02407837,0.015068054,-0.07989502,0.013328552,-0.02633667,0.027160645,-0.026184082,-0.038269043,0.024642944,-0.0