INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('20940934-dd86-4ad5-b147-00fe8c0fe1d8', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 60.5, 120.9, 'So last, on Tuesday, you saw two ways of implementing the set interface, right, one using just an unsorted array, just I threw these things in an array, and I could do a linear scan of my items to support basically any of these operations. It''s a little exercise you can go through. I think they show it to you in the recitation notes, but if you''d like to implement it for yourself, that''s fine. And then we saw a slightly better data structure, at least for the find operations. Can I look something up, whether this key is in my set interface? We can do that faster. We can do that in log n time with a build overhead that''s about n log n, right? Because we showed you three ways to sort. Two of them were n squared. One of them was n log n, which is as good as we showed you how to do yesterday. So the question then becomes, can I build that data structure faster?', '', '[-0.06768799,-0.011016846,0.01739502,-0.049316406,0.0011491776,0.0138168335,0.040496826,0.0074806213,0.051208496,-0.028640747,0.0052719116,0.0048332214,0.04562378,0.059448242,0.0042304993,0.005252838,-0.010215759,0.0005106926,-0.020935059,0.03842163,0.051116943,-0.017059326,-0.061706543,-0.072753906,0.038757324,0.062683105,-0.047912598,-0.028060913,-0.033325195,-0.25219727,-0.0051879883,-0.03515625,0.091552734,-0.021499634,-0.015029907,-0.03652954,-0.032806396,0.08129883,-0.052124023,0.025222778,0.02293396,0.032440186,-0.013908386,-0.07556152,-0.030288696,-0.033935547,-0.025970459,-0.024734497,-0.0012950897,-0.064086914,-0.017547607,-0.031341553,0.047698975,0.043762207,0.064575195,0.019607544,0.031982422,0.010955811,0.017745972,0.020095825,0.05630493,-0.0059127808,-0.15808105,0.115234375,0.025848389,-0.008049011,-0.0004544258,-0.055267334,0.013717651,0.058776855,-0.039123535,0.016937256,0.05340576,0.03729248