INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('9c630172-7199-4fe3-86da-d74eb4aad056', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 121.04, 189.16, 'That''ll be a subject of next week''s Thursday lecture. But this week, we''re going to concentrate on this static find, right? We got log n, which is an exponential improvement over linear, right? But the question here now becomes, can I do faster than log n time? And what we''re going to do at the first part of this lecture is show you that no. What''s up? What? No? Okay. That you can''t do faster than log n time in the caveat that we are in a slightly more restricted model of computation. That we were, than what we introduced to you a couple weeks ago. And then show if we''re not in that, that more constrained model of computation, we can actually do faster, right? And doing faster, I mean, log n''s already pretty good, right? Log n is not going to be larger than like 30 for any problem that you''re going to be talking about in the real world on real computers.', '', '[-0.084228516,-0.0019931793,0.026885986,-0.057678223,0.0005598068,0.03668213,0.026779175,0.023620605,0.051452637,-0.021560669,0.03842163,-0.0052719116,0.033843994,0.058685303,0.025665283,0.012245178,-0.01259613,-0.0047950745,-0.05834961,0.030517578,0.06213379,-0.041290283,-0.045959473,-0.07659912,0.033325195,0.0104904175,-0.05105591,-0.030822754,-0.014350891,-0.25805664,0.002714157,-0.055267334,0.08355713,-0.020065308,0.010650635,-0.026351929,-0.019363403,0.087402344,-0.046783447,0.050201416,0.032104492,0.07312012,-0.025619507,-0.059570312,-0.026794434,-0.03048706,-0.0524292,-0.012687683,-0.03857422,-0.04647827,-0.019515991,-0.01789856,0.0435791,0.004875183,0.023071289,0.03213501,0.028320312,-0.009483337,0.030654907,-0.003955841,0.025100708,0.06097412,-0.18676758,0.09741211,0.050994873,-0.014099121,-0.032226562,-0.04751587,0.0075035095,0.09942627,-0.02305603,0.051361084,0.022918701,0.049865723,0.0197143