INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('d4776a6e-7b8d-4f4e-898e-205ce207832d', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 189.16, 251.62, 'But a factor of 30 is still bad, right? I would prefer to do faster with those constant factors when I can. It''s not a constant factor. It''s a logarithmic factor. But you get what I''m saying. Okay. So what we''re going to do is first prove that you can''t do faster for find. Does everyone understand, remember what find key meant, right? I have a key. I have a bunch of items that have keys associated with them. And I want to see if one of the items that I''m storing contains a key that is the same as the one that I searched for, right? The item might contain other things. But in particular, it has a search key that I''m maintaining the set on so that it supports find operations, search operations, based on that key quickly. Does that make sense? So there''s the find one that we want to improve. And we also want to improve this insert, delete. We want to make this data structure dynamic, right? Because we might do those operations quite a bit.', '', '[-0.07836914,-0.016433716,-0.009902954,-0.053741455,-0.004142761,0.019348145,0.064453125,-0.015419006,0.026168823,-0.023880005,0.033477783,-0.034942627,0.053222656,0.026550293,-0.011039734,0.0020542145,-0.02859497,0.011161804,-0.04296875,0.020568848,0.05807495,-0.049987793,-0.034576416,-0.09637451,0.047821045,0.05255127,-0.055603027,-0.033966064,-0.051818848,-0.25097656,-0.039916992,-0.023956299,0.10449219,-0.014137268,-0.0074653625,0.014808655,-0.00881958,0.062683105,-0.07196045,0.064697266,0.0009126663,0.023040771,-0.0068511963,-0.015144348,-0.040863037,-0.016998291,-0.05822754,-0.017852783,0.016113281,-0.015701294,-0.018478394,0.009262085,0.013442993,0.07751465,0.015235901,0.03741455,0.052124023,0.017150879,0.02609253,0.006259918,0.06112671,0.023834229,-0.13024902,0.08917236,0.03955078,0.005455017,-0.0015249252,-0.0857