INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('773677b0-7697-4889-81fb-1bd9e6ef83c6', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 251.62, 311.68, 'And so this lecture is about optimizing those three things. Okay. So first I''m going to show you that we can''t do faster than log n for find, which is a little weird. Okay. The model of computation I''m going to be proving this lower bound on, right? I''m saying that how I''m going to approach this is I''m going to say that any way that I store these, the items that I''m storing in this data structure, for any way I store these things, any algorithm of this certain type is going to require at least logarithmic time. That''s what we''re going to try to prove. And the model of computation that''s weaker than what we''ve been talking about previously is what I''m going to call the comparison model. And a comparison model means is that the items, the objects I''m storing, I can kind of think of them as black boxes.', '', '[-0.07562256,0.038146973,0.0027179718,-0.024612427,0.038146973,0.030212402,0.027023315,0.024673462,0.043945312,-0.044128418,0.0013246536,-0.037506104,0.019561768,0.054870605,0.0028076172,-0.021209717,-0.026885986,0.0026054382,-0.03149414,-0.002904892,0.086242676,-0.042114258,-0.06896973,-0.06414795,0.04623413,0.01676941,-0.052337646,-0.00042700768,-0.010437012,-0.25854492,0.00059604645,-0.056274414,0.091552734,-0.033081055,0.012145996,-0.02418518,-0.010368347,0.057678223,-0.079956055,0.022232056,0.026168823,0.064941406,-0.016540527,-0.028045654,-0.029373169,-0.045562744,-0.032562256,-0.008781433,-0.016586304,-0.061920166,-0.02748108,-0.03149414,-0.0063705444,0.020874023,0.02748108,0.03363037,0.056762695,0.027740479,0.022644043,-0.010505676,0.01838684,0.054260254,-0.15881348,0.0758667,0.03265381,0.008903503,-0.00756073,-0.07434082,0.03213501,0.07836914,-0.029525757,0.040802002,0.013923645,0.03503418,0.008361816,-0.0029582977,-0.017089844,-0.046051025,0.0