INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('e3beb717-ebc1-47ce-b31f-8cdb79d55209', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 312.08, 377.44, 'I don''t get to touch these things, except the only way that I can distinguish between them is to say, given a key and an item or two items, I can do a comparison on those keys, right? Are these keys the same? Is this key bigger than this one? Is it smaller than this one? Those are kind of the only operations I get to do with them. I don''t get to look at what the, say, if the keys are numbers, I don''t get to look at what number that is, right? I just get to take two keys and compare them. And actually, all of the search algorithms that we saw on Tuesday were comparison sort algorithms, right? What you did was you stepped through the program. At some point, you came to a branch, and you looked at two keys, and you branched based on whether one key was bigger than another, right? That was a comparison. And then you moved some stuff around, but that was the general paradigm. Those three sorting operations lived in this comparison model, right?', '', '[-0.06719971,-0.04107666,-0.022384644,-0.03567505,0.022583008,-0.004951477,0.075683594,0.00548172,0.03543091,-0.0440979,0.01965332,-0.026367188,0.035247803,0.007873535,-0.0029201508,-0.0050849915,-0.041931152,-0.017486572,-0.06732178,0.014099121,0.06237793,0.005317688,-0.06341553,-0.061767578,0.031829834,0.05065918,-0.031921387,-0.0037174225,-0.044311523,-0.25830078,-0.017028809,-0.030136108,0.10235596,-0.026504517,0.00116539,-0.034301758,-0.010948181,0.04336548,-0.07824707,0.011428833,0.03237915,0.004814148,-0.0059280396,-0.0072784424,-0.025421143,-0.076049805,-0.04763794,0.035186768,0.000518322,-0.0501709,0.02017212,-0.03881836,0.0012073517,0.03164673,0.046813965,0.029418945,0.062042236,0.043884277,0.03933716,0.023956299,0.084350586,0.015899658,-0.18408203,0.11828613,0.036071777,0.030761719,-0.013114929,-0.09838867,0.0431