INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('7cb575a4-4a32-4a2f-ba6d-00074a7fa225', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 907.78, 969.72, 'That was a super powerful thing because within a single constant time operation, I could go to any space in memory, right? That''s potentially much larger than linear branching factor depending on the size of my model and the size of my machine, right? So that''s a very powerful operation. Can we use that to find quicker? Anyone have any ideas? Sure. We''re going to get to hashing in a second, but this is a simpler concept than hashing, something you probably are familiar with already. We''ve kind of been using it implicitly in some of our sequence data structure things. What we''re going to do is if I have an item that has key 10, I''m going to keep an array and store that item 10 spaces away from the front of the array, right? At index 9 or the 10th index.', '', '[-0.04824829,-0.021102905,0.0020561218,-0.030456543,0.027923584,-0.009483337,0.040924072,0.018310547,0.040222168,-0.036254883,0.0146484375,-0.032836914,0.025268555,0.02218628,-0.013061523,-0.019805908,-0.035217285,0.045043945,-0.04421997,0.01965332,0.07647705,-0.022842407,-0.005168915,-0.06112671,0.029586792,0.05807495,-0.03942871,-0.012634277,-0.044189453,-0.2529297,-0.008262634,-0.06512451,0.09906006,0.0017194748,0.017944336,-0.03857422,-0.01838684,0.055480957,-0.08441162,0.068359375,0.037719727,0.02671814,-0.036224365,-0.012077332,-0.03237915,-0.04534912,-0.050598145,-0.012741089,0.037994385,-0.058807373,-0.008644104,0.0043563843,-0.021743774,0.055419922,0.03994751,0.004055023,0.08227539,-0.0031814575,0.026901245,-0.03427124,0.06561279,0.002916336,-0.140625,0.06323242,0.070617676,-0.0143585205,-0.005531311,-0.021652222,0.0055160522,0.04019165,-0.05355835,0.032806396,0.0059127808,0.06347656,0.03253174,-0.05239868,-0.013679504,-0.015487671,0.018859863,0.0284729,-0.031066895,-0.06781006,-0.0085372925,-0.0316