INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('f2421522-32ac-45f4-bd97-65d7181b6af5', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 1348.16, 1409.18, 'But this is kind of the assumption. In this class, when we give you like an array of integers or an array of strings or something like that on your problem set or on an exam, right? The assumption is unless we give you bounds on the size of those things, right? Like the number of characters in your string or the size of the number in the thing, you can assume that those things will fit in in one word of memory, okay? W is the word size of your machine, right? The number of bits that your machine can do operations on in constant time. Any other questions? Okay, so we have this problem. We''re using way too much space, right? When we have a large universe of keys. So, how do we get around that problem? Any ideas? Sure.', '', '[-0.05206299,-0.032226562,0.028808594,-0.0725708,-0.027999878,-0.007686615,0.08093262,0.038482666,0.031585693,-0.040618896,0.022216797,-0.01146698,0.039611816,0.016998291,-0.002779007,-0.00592041,-0.016189575,-0.022262573,-0.049987793,0.024429321,0.1060791,-0.0029144287,-0.028411865,-0.04824829,-0.017074585,0.052825928,-0.028564453,-0.056732178,-0.022979736,-0.22290039,-0.027130127,-0.023269653,0.090148926,-0.032196045,0.019134521,-0.007419586,-0.021194458,0.037017822,-0.07745361,0.06463623,0.014785767,0.045013428,-0.016174316,-0.025619507,-0.014839172,-0.055603027,-0.05593872,-0.038146973,-0.0056991577,-0.03665161,-0.006351471,-0.010765076,0.012512207,0.05456543,0.0029449463,0.026290894,0.04949951,0.03463745,0.027267456,-0.00049448013,0.014038086,0.0061073303,-0.15783691,0.105163574,0.01828003,0.0018882751,-0.01335144,-0.02444458,0.023086548,0.07495117,-0.01222229,0.020248413,0.029403687,0.12176514,0.033416748,-0.0035095215,-0.025512695,8.08239e-05,0.05316162,0.041534424,-0.06317139,-0.0847168,-0.012809753,-0.00868988,-0.060424805,-0.05206299,-0.