INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('e7ab1d60-3db1-48b5-a8d1-b324f305f49d', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 1604.04, 1668.88, 'Just based on pigeonhole principle, I have more of these things. At least two of them have to go to something over here. In fact, if I have, say, u is bigger than n squared, for example, right? For any function I give you that maps this large space down to the small space, n of these things will map to the same place, right? So if I choose a bad function here, then I''ll have to store n things at the same index location, and if I go there, I have to kind of check to see whether any of those are the things that I''m looking for. I haven''t gained anything, right? I really want a hash function that will evenly distribute keys over this space, right? Does that make sense? But we have a problem here. If we need to store multiple things at a given location in memory, I can''t do that. I have one thing I can put there. So I have two options on how to deal what I call collisions, right?', '', '[-0.06933594,-0.056243896,0.008644104,-0.047546387,-0.024978638,0.03363037,0.061553955,0.022003174,0.043182373,-0.007713318,-0.011497498,-0.035491943,0.047851562,0.056518555,0.006969452,0.00028920174,-0.01499176,0.036895752,-0.06109619,-0.020828247,0.03074646,-0.02154541,-0.023605347,-0.037139893,-0.0014648438,0.0748291,-0.03945923,-0.027374268,-0.04046631,-0.25878906,0.040527344,-0.031433105,0.031433105,-0.032348633,0.012924194,-0.03475952,-0.009284973,0.058685303,-0.01940918,0.045410156,0.07128906,0.038604736,-0.037994385,-0.033203125,-0.002752304,-0.042785645,-0.033447266,-0.033447266,0.008049011,-0.0309906,0.0010557175,-0.012428284,0.0042686462,0.021194458,0.040039062,0.028930664,0.038391113,0.073791504,0.024337769,0.022994995,0.06567383,0.011459351,-0.09454346,0.09106445,0.053649902,-0.013328552,-0.0071983337,-0.02923584,0.023895264,0.09375,0.0076522827,0.06719971,-5.8352947e-05,