INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('34d6e68a-08e3-4ff6-8304-b9e9e3d2bbd6', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 1804.24, 1871.42, 'Python uses an open addressing scheme, which is essentially find another place in the array to put this collision. But open addressing is notoriously difficult to analyze, so we''re not going to do that in this class. There''s a much easier technique that we have an implementation for you in the recitation handouts. It''s what your colleague up here, I can''t find him, over there was saying was instead of storing it somewhere else in the existing direct access array down here, which we usually call the hash table, right, instead of storing it somewhere else in that hash table, we''ll instead, at that key, store a pointer to another data structure. Right? Some other data structure that can store a bunch of things, just like any sequence data structure, like a dynamic array or a linked list or anything, right? All I need to do is be able to stick a bunch of things on there when there are collisions, and then when I go up to look for that thing, I''ll just look through all of the things in that data structure and see if my key exists.', '', '[-0.05718994,-0.06329346,0.00970459,-0.04864502,-0.015853882,-0.0067329407,0.07965088,0.033843994,0.054748535,-0.046539307,0.0178833,-0.03704834,0.053955078,0.020324707,-0.0077590942,-0.06402588,-0.027328491,0.03314209,-0.012771606,-0.00045514107,0.019195557,0.0027561188,-0.04232788,-0.030426025,0.00579834,0.10028076,-0.038513184,-0.0052986145,-0.033294678,-0.24316406,0.024337769,-0.07543945,0.04220581,-0.023223877,-0.0140686035,-0.028564453,-0.025558472,0.05871582,-0.03201294,0.06750488,0.0435791,0.035064697,-0.045776367,-0.03756714,-0.009712219,-0.006778717,-0.036499023,-0.04498291,0.06591797,-0.03137207,-0.048980713,0.0017681122,-0.007209778,0.013084412,0.045196533,0.036071777,0.08996582,0.052001953,0.022094727,0.0054473877,0.042