INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('c55697a1-619e-41e4-82ea-32a73490a280', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 1932.6, 1993.46, 'Does that make sense? So this is an idea called chaining, I can put anything I want there. Commonly, we talk about putting a linked list there, but you can put, you know, a dynamic array there, you can put a sorted array there to make it easier to check whether the key is there, you can put anything you want there. The point of this lecture is going to try to show that there''s a choice of hash function I can make that makes sure that these chains are small so that it really doesn''t matter how I store them there, right? Because I can just, I have time, if there''s a constant number of things stored there, I can just look at all of them and do whatever I want and still get constant time. Yeah? So, does that mean that when you have a hash table, a multiple slot is like a data structure and like, let''s just say like, for some reason, the number of things you can store is that most of them get like multiple and if you have just one, is it just a data structure that only goes along to me?', '', '[-0.05831909,-0.03479004,-0.005268097,-0.06768799,-0.0042648315,0.017227173,0.059753418,0.0014305115,0.015220642,-0.015853882,0.028366089,0.0061912537,0.0635376,0.06573486,-0.004459381,-0.023971558,-0.012557983,0.01776123,-0.036743164,0.019363403,0.072387695,-0.023803711,-0.03186035,-0.036743164,0.015106201,0.08685303,-0.031311035,-0.041748047,-0.036743164,-0.20861816,0.006439209,-0.052764893,0.0524292,-0.05227661,-0.044799805,-0.054748535,-0.021331787,0.052001953,-0.052368164,0.047546387,0.06390381,0.04434204,-0.050811768,-0.020126343,-0.027679443,-0.036834717,-0.068359375,-0.03274536,0.009643555,-0.050048828,-0.032592773,0.033813477,-0.0012454987,0.03591919,0.045318604,0.028900146,0.07220459,0.070495605,-0.0005145073,0.018936157,0.08081055,0.070007324,-0.080444336,0.08807373,0.