INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('c5e5471c-5859-4cc6-ad62-b5711399c41b', 'fccf9845-d93f-41e9-9a3e-edd2c1eda37e', 1993.52, 2056.02, 'Yeah, so what your colleague is saying is kind of at initialization, what is stored here, right? Initially, it points to an empty data structure, right? I''m just going to initialize all of these things to have, now, we get some overhead here, right? We''re paying something for this, some extra space and having pointer and another data structure at all of these things or you could have the semantics where if I only have one thing here, I''m going to store that thing at this location but if I have multiple, it points to a data structure. These are kind of complicated, you know, implementation details but you get the basic idea, right? If I just have a zero size data structure at all of these things, I''m still going to have a constant factor overhead, right? It''s still going to be a linear size data structure as long as M is linear in N. Does that make sense? Okay, so how do we pick a good hash function? I already told you that any fixed hash function I give you is going to experience collisions and if U is large, right?', '', '[-0.0423584,-0.018371582,-0.037109375,-0.054748535,-0.019958496,0.027450562,0.06439209,0.021987915,0.02508545,-0.056121826,0.033111572,-0.03652954,0.057525635,0.050109863,0.014266968,-0.012023926,0.004436493,-0.02027893,-0.03729248,0.028549194,0.055603027,-0.045318604,-0.026916504,-0.035308838,-0.007030487,0.09954834,-0.04437256,0.0104904175,-0.0129776,-0.24194336,0.0057792664,-0.043121338,0.08441162,-0.05316162,-0.016204834,-0.04949951,0.014305115,0.055847168,-0.028274536,0.054656982,0.06982422,0.055664062,-0.07354736,-0.012817383,-0.02319336,-0.03152466,-0.06347656,-0.025405884,0.02760315,-0.02998352,-0.036315918,0.028533936,0.011360168,0.034942627,0.057800293,0.040252686,0.09399414,0.051239014,0.0032253265,0.009391785,0.05154419,0.05142212,