INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('b5f67312-efd2-443d-ac36-77c95cecfa5a', '9736166c-3585-4b19-ac9b-48b30e3242ac', 60.76, 121.04, 'Incidentally, typically I teach the intro graphics class, a geometry course, and last year I got feedback that said I have serial killer handwriting. I''m not 100% sure what that means. But we''re going to use the slides a tiny bit more than normal just to make sure you guys can read. And when I''m writing on the board at any point, if you can''t tell what I wrote, it''s definitely me and not you. So just let me know. But in any event, in 6006, all the way back in our lecture one, I know that was a long time ago, we introduced two big keywords that are closely related but not precisely the same. Hopefully I''ve gotten this right. But roughly, there''s a theme here, which is that there''s an object called an interface, which is just sort of like a program specification. It''s just telling us that there''s a collection of operations that we want to implement. So for example, a set, as we''re going to see today, is like a big pile of things. And behind the scenes, how I choose to implement it can affect the runtime and sort of how efficient my set is.', '', '[-0.06210327,-0.014732361,0.035614014,-0.01928711,-0.0038986206,-0.012748718,0.06365967,0.03173828,0.02557373,-0.03414917,-0.0002937317,-0.009407043,0.018936157,0.044433594,-0.046813965,-0.038909912,-0.020874023,0.011039734,-0.0102005005,0.00737381,0.121398926,0.02696228,-0.010971069,-0.07098389,0.009819031,0.0914917,-0.04537964,-0.008323669,-0.029830933,-0.19506836,-0.004852295,-0.023208618,0.05432129,-0.018722534,0.0023555756,0.0007853508,-0.03692627,0.08166504,-0.050354004,0.03250122,0.039978027,0.033203125,9.483099e-05,-0.041137695,-0.035736084,-0.06878662,-0.011367798,-0.033691406,-0.007789612,-0.052246094,-0.012458801,-0.04434204,0.0056877136,0.02079773,0.020233154,-0.010009766,0.08380127,0.03164673,0.010795593,0