INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('eaf41433-abea-4847-aaf5-2429adda6625', '9736166c-3585-4b19-ac9b-48b30e3242ac', 121.04, 181.1, 'But the actual way that I interact with it is the same, whether I use an unsorted array, a sorted array, or what have you. On the other hand, what happens behind the scenes is something called a data structure, which is a way to actually, in some sense, implement an interface. So this is the object that on my computer is actually storing the information and implementing the set of operations that I''ve laid out in my interface. And so this sort of distinction, I think, is sort of a critical theme in this course. Because for instance, in the first couple weeks, we''re going to talk about many different ways to implement a set. And we''re going to see that there''s a bunch of trade-offs. Some of them are really fast for certain operations and slow for others. And so essentially, we have two different decisions to make when we choose an algorithm. One is making sure that the interface is correct for the problem that we''re concerned with. And the other is choosing an appropriate data structure whose efficiency and memory usage and so on kind of aligns with the priorities that we have for the application we have in mind. So hopefully this kind of high-level theme makes sense.', '', '[-0.07220459,-0.01927185,0.021850586,-0.045196533,0.024856567,-0.007785797,0.087890625,0.009277344,0.07348633,-0.030349731,0.005722046,0.02609253,0.035491943,0.05343628,-0.008903503,7.5399876e-05,-0.021560669,-0.027359009,-0.027877808,0.019744873,0.059570312,-0.014770508,-0.062927246,-0.06903076,0.018234253,0.08959961,-0.06088257,-0.024475098,-0.026168823,-0.21179199,-0.008628845,-0.030212402,0.09857178,-0.04095459,-0.034179688,-0.030151367,-0.016906738,0.04824829,-0.076416016,0.023742676,0.031463623,-0.013320923,-0.024398804,-0.041809082,-0.032470703,-0.022354126,-0.02923584,-0.013954163,-0.007