INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('875c60c7-dc6a-48f5-8bad-f484f68e2477', '9736166c-3585-4b19-ac9b-48b30e3242ac', 242.62, 307.78, 'And the set of students that are in 6006. And if it does, then I can pull that student back. And then associated with that object is a bunch of other information that I''m not using to search. So for instance, your name, your social security number, credit card number, all the stuff that I need to have a more interesting profession. So in any event, let''s kind of fill in the details of our set interface a little bit more. So our set is a container. It contains all of the students in this classroom, in some virtual sense at least. And so to build up our set, of course, we need an operation that takes some iterable object A and builds a set out of it. So in other words, I have all the students in this classroom represented maybe in some other fashion, and I have to insert them all into my set. I can also ask my set for how much stuff is in it. Personally, I would call that size, but length is cool too. And then, of course, there are a lot of different ways that we can interact with our set. So for instance, we could say, you know, is this student taking 6006?', '', '[-0.036987305,-0.0061416626,0.026992798,-0.07080078,-0.0019016266,-0.01991272,0.085754395,-3.8266182e-05,-0.005130768,-0.020217896,0.018753052,-0.028366089,0.010620117,0.030715942,-0.021240234,-0.016693115,-0.020980835,0.012512207,-0.052490234,0.013298035,0.07757568,-0.015914917,-0.039978027,-0.048217773,0.013946533,0.077697754,-0.045288086,-0.045776367,-0.03503418,-0.18457031,0.017364502,-0.041229248,0.0847168,-0.01146698,0.023483276,0.009506226,-0.0011234283,0.069885254,-0.036010742,0.04748535,0.062683105,-0.0036373138,-0.028762817,-0.023284912,-0.050567627,-0.03302002,-0.03543091,-0.048706055,0.005115509,-0.020019531,0.003522873,-0.06518555,0.012413025,0.059326172,-0.005393982,0.062164307,0.08660889,0.019