INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('7d55174a-2cd9-4e59-a112-eb8cdfd0b2d9', '9736166c-3585-4b19-ac9b-48b30e3242ac', 1577.78, 1639.76, 'I see your hand, but we''re going to defer for a little bit. I''m sorry? . That''s fabulous. Why don''t we defer to the end of lecture, and we''ll do it then. OK. So the first algorithm that we''ll talk about for sorting, which is somewhat sensible, is something called selection sort. Selection sort is exactly what it sounds like. So let''s say that we have a list of, oops. My laptop and the screen are not green. OK. Let''s say I have a list of numbers 82493. This is a message that Jason, I think, is sending me in the course notes, but I haven''t figured it out. But in any event, and I want to sort this list of numbers. Here''s a simple algorithm for how to do it, which is I can find the biggest number in this whole list and stick it at the end. Yeah? So in this case, what''s the biggest number in this list, everybody? 9. 9. See, this is why you go to MIT. OK. So I''m going to take that 9, find it, and then swap it out with the 3, which is at the end. And now what''s my sort of inductive hypothesis?', 'in key order
