INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('39ed5e04-618b-43b9-b04f-ec3617b00d06', '9736166c-3585-4b19-ac9b-48b30e3242ac', 1709.26, 1770.9, 'Now, I can''t emphasize strongly enough how little you guys should implement this at home. This is mostly a theoretical version of selection sort, rather than one that you would actually want to write in code, because there''s obviously a much better way to do it, and you''ll see that in your recitation this week, I believe. But in terms of analysis, there''s a nice, easy way to write it down. So we''re going to sort of take this election sort algorithm, and we''re going to divide it into two kind of chunks. One of them is find me the biggest thing in the first k elements of my array. I shouldn''t use k, because that means key. The first i elements of my array. And the next one is to swap it into place, and then sort everything to the left. That''s sort of the two pieces here. Let''s write that down. OK, so what did I do? Well, in some sense, in step one here, I found the biggest with index less than or equal to i.', 'in key order
