INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('2a3b7a1e-1a8d-4cc1-ab64-441fecdbffec', '9736166c-3585-4b19-ac9b-48b30e3242ac', 1959, 2020, 'In this case, that is 8. There we go. Now, I look at the very last element of my array, which is 9. You''re killing me today, guys. OK? And then what do I return? Well, I want the biggest one between 0 and index i. So in this case, I return the 9. Does that make sense? OK? So, you know, there''s this, I know Jerry Kane at Stanford likes to talk about the, what is it, the recursive leap of faith that happens. Another term for this is induction. Right? So we want to prove that our algorithm works. Well, what do we have to do? We have to show that when I call this function, it gives me the max of my array between index 0 and index i for all i. Right? So let''s maybe do this inductive proof a little bit carefully, and then the rest will be sloppy about it. Right? So the base case is i equals 0. Right? Well, in this case, there''s only one element in my array, so it''s pretty clear that it''s the max.', 'in key order
smallest key
largest key
smallest key larger than k
largest key smaller than k

