INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('3d252a03-5afd-4cdf-b42e-e68bf5772b4d', '9736166c-3585-4b19-ac9b-48b30e3242ac', 2203, 2263, 'And we just have to make sure that this is like an OK equal sign. So what can I do? I can subtract cn from both sides. Maybe put that 1 on the other side here. I''m going to get that c equals big O of 1. C is, of course, a constant, so we''re in good shape. My undergrad algorithms professor told me never to write a victory mark at the end of a proof. You have to do a little square. But he''s not here. OK. Right. So now I see you, but we''re a little low on time. So we''ll save it for the end of lecture. OK. So if we want to implement the selection sort algorithm, well, what do we do? Well, we''re going to think of i as the index of that red line that I was showing you before. So everything beyond i is already sorted. So in selection sort, the first thing I''m going to do is find the max element between 0 and i. And then I''m going to swap it into place.', 'in key order
