INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('923e203f-6820-4f55-b3b5-50a702dae998', '9736166c-3585-4b19-ac9b-48b30e3242ac', 2330, 2391, 'OK. So remember, there''s this nice relationship, which you probably learned in your combinatorics class. Which is that 1 plus 2 plus dot dot dot plus n. OK. I can never remember exactly the formula, but I''m pretty sure that it looks like n squared. Yeah. So based on that and taking a look at this recursive thing, which is essentially doing exactly that. Right. n plus n minus 1 plus n minus 2 and so on. I might hypothesize that this thing is really order n squared. So if I''m going to do that, then again, if I want to use the same technique for proof, I have to plug this relationship in and then double check that it''s consistent. Right. So maybe I hypothesize that T of n equals c n squared, in which case I plug it in here. I have c n squared equals with a question mark over it, c n minus 1 squared plus big O or even theta n here.', 'in key order
