INSERT INTO public.segments (id, lecture_id, start_s, end_s, transcript, slide_text, embedding) VALUES ('e0715df2-d4fb-480b-8401-b1cb2bbc1f7a', '9736166c-3585-4b19-ac9b-48b30e3242ac', 2698, 2758, 'So I think the merged sort we''re going to present in kind of a backward way from the previous one, where I''m going to give you the high-level algorithm. And then actually the headache is that merging step, which I have four minutes for, and I apologize for it. So what does the merged sort do? Well, it computes an index C, which is the middle of my array. And it''s going to make a recursive call, which is sort the left, which is everything between index A and index C. And then sort everything on the right, which is everything from index C to index B. I know this is confusing because usually letters appear in order. So if you want C, if you think of it as standing for center, then it kind of makes sense. Like, here''s my array. I''m going to choose an index right in the middle. I''ve done myself a disservice by not using a power of 2, but that''s OK. I''m going to say, sort everything to the left of the dotted line first. Sort everything to the right of the dotted line second. Now I have two sorted lists on the two sides of the dotted line. And then I''m going to use my two fingers to put them together.', 'in key order
smallest key
largest key
smallest key larger than k
largest key smaller than k

